import 'package:flutter/material.dart'  import 'package:flutter_riverpod/flutter_riverpod.dart'  import 'package:go_router/go_router.dart'  import '../api/api_client.dart'  import '../providers/auth_provider.dart'    class RegisterScreen extends ConsumerStatefulWidget {    const RegisterScreen({super.key})      @override    ConsumerState<RegisterScreen> createState() => _RegisterScreenState()  }    class _RegisterScreenState extends ConsumerState<RegisterScreen> {    final _emailController = TextEditingController()    final _passwordController = TextEditingController()    final _confirmPasswordController = TextEditingController()    final _fullNameController = TextEditingController()    final _phoneController = TextEditingController()    final _formKey = GlobalKey<FormState>()    bool _isLoading = false    bool _obscurePassword = true    bool _acceptTerms = false      @override    void dispose() {      _emailController.dispose()      _passwordController.dispose()      _confirmPasswordController.dispose()      _fullNameController.dispose()      _phoneController.dispose()      super.dispose()    }      Future<void> _register() async {      if (!_formKey.currentState!.validate()) return      if (!_acceptTerms) {        ScaffoldMessenger.of(context).showSnackBar(          const SnackBar(content: Text('Примите условия использования')),        )        return      }        setState(() => _isLoading = true)      try {        await ApiClient().register({          'email': _emailController.text.trim(),          'password': _passwordController.text,          'full_name': _fullNameController.text.trim(),          'phone': _phoneController.text.trim(),        })        if (mounted) {          ScaffoldMessenger.of(context).showSnackBar(            const SnackBar(content: Text('Регистрация успешна! Войдите в систему.')),          )          context.go('/login')        }      } catch (e) {        if (mounted) {          ScaffoldMessenger.of(context).showSnackBar(            SnackBar(content: Text('Ошибка регистрации: $e'), backgroundColor: Colors.red),          )        }      } finally {        if (mounted) setState(() => _isLoading = false)      }    }      @override    Widget build(BuildContext context) {      return Scaffold(        appBar: AppBar(title: const Text('Регистрация')),        body: SafeArea(          child: SingleChildScrollView(            padding: const EdgeInsets.all(24),            child: Form(              key: _formKey,              child: Column(                crossAxisAlignment: CrossAxisAlignment.stretch,                children: [                  // Full name                  TextFormField(                    controller: _fullNameController,                    decoration: InputDecoration(                      labelText: 'Полное имя *',                      prefixIcon: const Icon(Icons.person_outline),                      border: OutlineInputBorder(borderRadius: BorderRadius.circular(12)),                    ),                    validator: (value) => value == null || value.isEmpty ? 'Введите имя' : null,                  ),                  const SizedBox(height: 16),                    // Email                  TextFormField(                    controller: _emailController,                    keyboardType: TextInputType.emailAddress,                    decoration: InputDecoration(                      labelText: 'Email *',                      prefixIcon: const Icon(Icons.email_outlined),                      border: OutlineInputBorder(borderRadius: BorderRadius.circular(12)),                    ),                    validator: (value) {                      if (value == null || value.isEmpty) return 'Введите email'                      if (!value.contains('@')) return 'Неверный email'                      return null                    },                  ),                  const SizedBox(height: 16),                    // Phone                  TextFormField(                    controller: _phoneController,                    keyboardType: TextInputType.phone,                    decoration: InputDecoration(                      labelText: 'Телефон',                      prefixIcon: const Icon(Icons.phone_outlined),                      border: OutlineInputBorder(borderRadius: BorderRadius.circular(12)),                    ),                  ),                  const SizedBox(height: 16),                    // Password                  TextFormField(                    controller: _passwordController,                    obscureText: _obscurePassword,                    decoration: InputDecoration(                      labelText: 'Пароль *',                      prefixIcon: const Icon(Icons.lock_outline),                      suffixIcon: IconButton(                        icon: Icon(_obscurePassword ? Icons.visibility_off : Icons.visibility),                        onPressed: () => setState(() => _obscurePassword = !_obscurePassword),                      ),                      border: OutlineInputBorder(borderRadius: BorderRadius.circular(12)),                    ),                    validator: (value) {                      if (value == null || value.isEmpty) return 'Введите пароль'                      if (value.length < 8) return 'Минимум 8 символов'                      return null                    },                  ),                  const SizedBox(height: 16),                    // Confirm password                  TextFormField(                    controller: _confirmPasswordController,                    obscureText: _obscurePassword,                    decoration: InputDecoration(                      labelText: 'Подтвердите пароль *',                      prefixIcon: const Icon(Icons.lock_outline),                      border: OutlineInputBorder(borderRadius: BorderRadius.circular(12)),                    ),                    validator: (value) {                      if (value != _passwordController.text) return 'Пароли не совпадают'                      return null                    },                  ),                  const SizedBox(height: 16),                    // Terms                  Row(                    children: [                      Checkbox(                        value: _acceptTerms,                        onChanged: (v) => setState(() => _acceptTerms = v ?? false),                      ),                      Expanded(                        child: Text(                          'Я принимаю условия использования и политику конфиденциальности',                          style: TextStyle(fontSize: 12, color: Colors.grey[600]),                        ),                      ),                    ],                  ),                  const SizedBox(height: 24),                    // Register button                  ElevatedButton(                    onPressed: _isLoading ? null : _register,                    style: ElevatedButton.styleFrom(                      padding: const EdgeInsets.symmetric(vertical: 16),                      shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(12)),                    ),                    child: _isLoading                      ? const SizedBox(height: 20, width: 20, child: CircularProgressIndicator(strokeWidth: 2))                      : const Text('Зарегистрироваться', style: TextStyle(fontSize: 16)),                  ),                  const SizedBox(height: 16),                    // Login link                  Row(                    mainAxisAlignment: MainAxisAlignment.center,                    children: [                      Text('Уже есть аккаунт? ', style: TextStyle(color: Colors.grey[600])),                      TextButton(                        onPressed: () => context.go('/login'),                        child: const Text('Войти'),                      ),                    ],                  ),                ],              ),            ),          ),        ),      )    }  }